def art_box(a):
   return f'<div class="gq-art gq-art-{e(a["art"])}" role="img" aria-label="Decorative editorial motif"><div class="gq-art-orbit"></div><div class="gq-art-figure">{e(art_mark[a["art"]])}</div><div class="gq-art-stripe"></div><span class="gq-art-caption">THE GOOD QUESTION PAPER / 002</span></div>'

def graphic(a,l,t):
  if a['id']=='climate':
   return f'''<figure class="data-interlude"><figcaption>DATA, NOT DRAMA &nbsp; / &nbsp; NATURE FOOD · 2023</figcaption><div class="story-bars"><div><span>{'Fleischreich' if l=='de' else 'High meat' if l=='en' else 'Ăn nhiều thịt'}</span><div class="story-track"><i style="width:100%"></i></div><b>100%</b></div><div><span>{'Vegan' if l!='vi' else 'Thuần chay'}</span><div class="story-track vegan"><i style="width:25.1%"></i></div><b>25,1%</b></div></div><small>{e(t['comparison'])}</small></figure>'''
  if a['id']=='soy':
   return f'''<figure class="data-interlude soy-data"><figcaption>FOLLOW THE BEAN &nbsp; / &nbsp; GLOBAL ALLOCATION · 2018</figcaption><div class="soy-figure"><div class="soy-ring"><span>77<small>%</small></span></div><div><b>77%</b><span>{'Tierfutter' if l=='de' else 'Animal feed' if l=='en' else 'Thức ăn chăn nuôi'}</span><b>7%</b><span>{'Direkte Lebensmittel' if l=='de' else 'Direct human food' if l=='en' else 'Thực phẩm trực tiếp'}</span></div></div><small>{e(t['soylabel'])}</small></figure>'''
  if a['id']=='protein':
    return '<div class="key-mini"><strong>38</strong><span>12 WEEKS &nbsp; / &nbsp; PROTEIN-MATCHED TRIAL<br>HEVIA-LARRAÍN ET AL. · 2021</span></div>'
  if a['id']=='cost':
    return '<div class="key-mini"><strong>150</strong><span>COUNTRIES &nbsp; / &nbsp; MODELLING STUDY<br>SPRINGMANN ET AL. · 2021</span></div>'
  if a['id']=='harvest':
    return '<div class="key-mini unknown"><strong>?</strong><span>NO ROBUST GLOBAL DEATH COUNT<br>FISCHER & LAMEY · 2018</span></div>'
  if a['id']=='family':
    return '<div class="key-mini"><strong>2024</strong><span>DGE POSITION UPDATE<br>DIFFERENT GUIDANCE FOR VULNERABLE GROUPS</span></div>'
  return ''

def article_page(a,l,index):
 t=labels[l];x=a[l];headline=e(x['title']);sub=e(x['sub']);uid=a['id'];lang_opts=''.join(f'<a lang="{v}" hreflang="{v}" {"aria-current=page" if v==l else ""} href="../{v}/">{v.upper()}</a>' for v in ('de','en','vi'))
 src=''.join(f'''<li><span>0{i+1} &nbsp; / &nbsp; {e(S[k]['type'])}</span><h3>{e(S[k]['title'])}</h3><p>{e(S[k]['check'])}</p><a target="_blank" rel="noopener noreferrer" href="{e(S[k]['url'])}">{e(t['more'])} <span aria-hidden="true">↗</span></a></li>''' for i,k in enumerate(a['ref']))
 nxt=A[(index+1)%len(A)];prv=A[(index-1)%len(A)]
 meta_desc=e(x['sub'])
 side_claim=a['claim'] if l=='en' else claim_summary[uid][l]
 alternate=''.join(f'<link rel="alternate" hreflang="{v}" href="https://mikelninh.github.io/good-question/read/{uid}/{v}/">' for v in ('de','en','vi'))
 canonical=f'https://mikelninh.github.io/good-question/read/{uid}/{l}/'
 words=len(' '.join(x.get(k,'') for k in ('lead','best','finding','closer','uncertainty','action')).split())
 mins=max(2,round(words/180))
 jld=json.dumps({'@context':'https://schema.org','@type':'Article','headline':x['title'],'description':x['sub'],'datePublished':'2026-10-11','dateModified':'2026-10-11','author':{'@type':'Organization','name':'GOOD QUESTION editorial'},'publisher':{'@type':'Organization','name':'GOOD QUESTION'},'inLanguage':l,'mainEntityOfPage':canonical,'citation':[S[k]['url'] for k in a['ref']]},ensure_ascii=False).replace('<','\\u003c')
 return f'''<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{headline} · GOOD QUESTION / 002</title><meta name="description" content="{meta_desc}"><link rel="canonical" href="{canonical}">{alternate}<meta property="og:type" content="article"><meta property="og:title" content="{headline} · GOOD QUESTION"><meta property="og:description" content="{meta_desc}"><meta property="og:url" content="{canonical}"><meta name="theme-color" content="#f8f6ee"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Mono:wght@400;500&family=Fraunces:opsz,wght,SOFT,WONK@9..144,500,20,1;9..144,600,20,1;9..144,700,20,1&display=swap" rel="stylesheet"><link rel="stylesheet" href="../../../reader.css"><script type="application/ld+json">{jld}</script></head><body>
<a class="skip" href="#story">Skip to article</a><header class="reader-head"><div class="reader-nav"><a class="reader-brand" href="../../../"><span>g<span class="brand-spark">✳</span></span>good.question</a><nav aria-label="Main"><a href="../../../#issue">← {e(t['home'])}</a><a href="../../../#method">{e(t['origin'])}</a><a href="https://mikelninh.github.io/vegan/" target="_blank" rel="noopener noreferrer">{e(t['food'])} ↗</a></nav><div class="reader-langs" aria-label="Language">{lang_opts}</div></div></header>
<main id="story"><div class="story-paper"><div class="story-edition"><span>✳ &nbsp; THE GOOD QUESTION PAPER</span><span>{e(t['stamp'])}</span></div><div class="story-heading"><div><p class="story-kicker">{e(x['kicker'])}</p><h1>{headline}</h1><p class="story-sub">{sub}</p><div class="story-byline"><span>{e(t['editor'])}</span><span>{e(t['published'])}</span><span>{mins} {e(t['readtime'])}</span></div></div>{art_box(a)}</div>
{graphic(a,l,t)}
<div class="story-main"><div class="story-copy"><p class="story-lead">{e(x['lead'])}</p><section><p class="story-section-num">01 / THE OBJECTION</p><h2>{e(t['best'])}</h2><p>{e(x['best'])}</p></section><section><p class="story-section-num">02 / THE EVIDENCE</p><h2>{e(t['finding'])}</h2><p>{e(x['finding'])}</p><div class="story-deeper"><span>{e(x['closerTitle'])}</span><p>{e(x['closer'])}</p><div class="story-deeper-question"><b>✳</b> {e(x['betterQuestion'])}</div></div></section><blockquote><span aria-hidden="true">“</span>{e(x['quote'])}</blockquote><section><p class="story-section-num">03 / THE LIMITS</p><h2>{e(t['uncertainty'])}</h2><p>{e(x['uncertainty'])}</p></section><section class="story-step"><p class="story-section-num">04 / YOUR NEXT STEP</p><h2>{e(t['action'])}</h2><p>{e(x['action'])}</p><a href="https://mikelninh.github.io/vegan/" target="_blank" rel="noopener noreferrer">{e(t['love'])} ↗</a></section></div><aside class="story-aside"><div class="aside-inner"><p class="story-section-num">{e(t['glance'])}</p><h3>{e(t['claim'])}</h3><p>{e(side_claim)}</p><h3>{e(t['limitation'])}</h3><p>{e(x['uncertainty'])}</p><div class="aside-status">✳ &nbsp; {e(t['vetted'])}</div></div></aside></div>
<section class="story-receipts" id="sources"><div class="receipts-intro"><span class="story-section-num">05 / THE RECEIPTS</span><h2>{e(t['sources'])}</h2><p>{e(t['methodnote'])}</p></div><ol>{src}</ol><div class="receipts-check"><h3>{e(t['how'])}</h3><p>{e(t['checknote'])}</p><span>{e(t['checked'])}</span><a href="../../../issue02-evidence.json" target="_blank" rel="noopener noreferrer">EVIDENCE REGISTER ↗</a></div></section>
<div class="reader-end"><a href="../../{prv['id']}/{l}/"><span>← {e(t['prev'])}</span><strong>{e(prv[l]['title'])}</strong></a><a href="../../{nxt['id']}/{l}/"><span>{e(t['next'])} →</span><strong>{e(nxt[l]['title'])}</strong></a></div><div class="all-stories"><a href="../../../#issue-library">{e(t['explore'])} ↗</a></div></div></main><footer class="reader-footer"><span>© GOOD QUESTION 2026 · KINDNESS WITHOUT DOGMA</span><span>{e(t['disclaimer'])}</span></footer></body></html>'''

(base/'stories.js').write_text('/* Generated from stories.json — canonical editorial data */\nwindow.GQ_ISSUE2_DATA = '+json.dumps(D,ensure_ascii=False,separators=(',',':'))+';\n','utf-8')
for ix,a in enumerate(A):
 for l in ('de','en','vi'):
  out=base/'read'/a['id']/l/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(article_page(a,l,ix),'utf-8')
legacy=json.loads((base/'evidence-register.json').read_text('utf-8'))
claimrecords=[]
for i,a in enumerate(A,1):
 claimrecords.append({'id':f'ISS02-{i:02d}','article_id':a['id'],'claim':a['claim'],'qualitative_editorial_assessment':a['assessment'],'source_keys':a['ref'],'source_check':'Accessible original publisher pages, abstracts, institutional statements and/or secondary analyses compared; see per-source check details','limitations':a['limit'],'checked_on':'2026-10-11','independent_expert_review':'not_completed','formal_grade_assessment':False})
audit={'edition':'02','issued':'2026-10-11','last_editorial_check':'2026-10-11','audit_type':'AI-assisted manual claim-to-source check; not original-data reanalysis','external_subject_matter_review':'NOT COMPLETED','formal_grade_assessment':'NOT PERFORMED','source_count':len(S),'article_count':len(A),'source_registry':S,'claims':claimrecords,'limitations':'A citation alone is not proof; this register records the scope of checks actually performed. Ethical conclusions cannot be assigned a purely scientific confidence score.'}
(base/'issue02-evidence.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n','utf-8')
legacy['version']='2.0.0';legacy['issue02_register']='./issue02-evidence.json';legacy['issue02_article_count']=len(A);legacy['issue02_external_expert_review']='not_completed';legacy['checked_at']='2026-10-11'
(base/'evidence-register.json').write_text(json.dumps(legacy,ensure_ascii=False,indent=2)+'\n','utf-8')
urls=[f'https://mikelninh.github.io/good-question/read/{a["id"]}/{l}/' for a in A for l in ('de','en','vi')]
(base/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n<url><loc>https://mikelninh.github.io/good-question/</loc></url>\n'+''.join(f'<url><loc>{u}</loc></url>\n' for u in urls)+'</urlset>\n','utf-8')
print('Generated',len(urls),'localized reading pages + audit + sitemap.')
